import React, { useState, useEffect } from 'react';
import {
  Typography, Paper, Button, Table, TableBody, TableCell,
  TableContainer, TableHead, TableRow, IconButton, Dialog,
  DialogTitle, DialogContent, DialogActions, TextField, Box,
  Alert, FormControl, InputLabel, Select, MenuItem, Chip
} from '@mui/material';
import { Add, Edit, Delete, LockReset } from '@mui/icons-material';
import { realChecklistService } from '../../services/realApiService';

const UsersManagement = () => {
  const [users, setUsers] = useState([]);
  const [openDialog, setOpenDialog] = useState(false);
  const [editingUser, setEditingUser] = useState(null);
  const [newUser, setNewUser] = useState({ 
    username: '', 
    password: '',
    name: '', 
    role: 'operator', 
    area: '',
    is_active: true
  });
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');

  // Cargar usuarios desde la API
  const loadUsers = async () => {
    try {
      setLoading(true);
      const response = await realChecklistService.getUsers();
      if (response.data.success) {
        setUsers(response.data.users);
      }
    } catch (error) {
      setError('Error cargando usuarios: ' + error.message);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    loadUsers();
  }, []);

  const handleCreateUser = async () => {
    try {
      // Validar campos requeridos
      if (!newUser.username || !newUser.password || !newUser.name) {
        setError('Usuario, contraseña y nombre son obligatorios');
        return;
      }

      const response = await realChecklistService.createUser(newUser);
      if (response.data.success) {
        await loadUsers();
        setOpenDialog(false);
        setNewUser({ 
          username: '', 
          password: '',
          name: '', 
          role: 'operator', 
          area: '',
          is_active: true
        });
        setError('');
      }
    } catch (error) {
      setError('Error creando usuario: ' + error.message);
    }
  };

  const handleUpdateUser = async () => {
    try {
      const response = await realChecklistService.updateUser(editingUser.id, newUser);
      if (response.data.success) {
        await loadUsers();
        setOpenDialog(false);
        setEditingUser(null);
        setNewUser({ 
          username: '', 
          password: '',
          name: '', 
          role: 'operator', 
          area: '',
          is_active: true
        });
        setError('');
      }
    } catch (error) {
      setError('Error actualizando usuario: ' + error.message);
    }
  };

  const handleDeleteUser = async (id) => {
    if (window.confirm('¿Estás seguro de que quieres eliminar este usuario?')) {
      try {
        const response = await realChecklistService.deleteUser(id);
        if (response.data.success) {
          await loadUsers();
        }
      } catch (error) {
        setError('Error eliminando usuario: ' + error.message);
      }
    }
  };

  const handleEditUser = (user) => {
    setEditingUser(user);
    setNewUser({ 
      username: user.username,
      password: '', // No mostrar contraseña actual
      name: user.name, 
      role: user.role, 
      area: user.area || '',
      is_active: user.is_active
    });
    setOpenDialog(true);
  };

  const handleResetPassword = (userId) => {
    const newPassword = prompt('Ingrese la nueva contraseña para el usuario:');
    if (newPassword && newPassword.trim()) {
      // Aquí deberías llamar a un endpoint específico para resetear contraseña
      alert(`Contraseña reseteada a: ${newPassword}\n(En una implementación real, esto se enviaría al backend)`);
    }
  };

  const handleSave = () => {
    if (editingUser) {
      handleUpdateUser();
    } else {
      handleCreateUser();
    }
  };

  // Roles disponibles
  const roles = [
    { value: 'admin', label: 'Administrador' },
    { value: 'supervisor', label: 'Supervisor' },
    { value: 'operator', label: 'Operador' }
  ];

  // Áreas disponibles (deberías cargarlas de la API)
  const areas = [
    'Producción',
    'Calidad', 
    'Seguridad',
    'Mantenimiento',
    'Almacén',
    'Logística',
    'Administración'
  ];

  const getRoleColor = (role) => {
    switch(role) {
      case 'admin': return 'error';
      case 'supervisor': return 'warning';
      case 'operator': return 'success';
      default: return 'default';
    }
  };

  return (
    <Box>
      <Box sx={{ display: 'flex', justifyContent: 'space-between', mb: 3 }}>
        <Typography variant="h4">
          Gestión de Usuarios
        </Typography>
        <Button
          variant="contained"
          startIcon={<Add />}
          onClick={() => {
            setEditingUser(null);
            setNewUser({ 
              username: '', 
              password: '',
              name: '', 
              role: 'operator', 
              area: '',
              is_active: true
            });
            setOpenDialog(true);
          }}
        >
          Nuevo Usuario
        </Button>
      </Box>

      {error && (
        <Alert severity="error" sx={{ mb: 2 }} onClose={() => setError('')}>
          {error}
        </Alert>
      )}

      <TableContainer component={Paper}>
        <Table>
          <TableHead>
            <TableRow>
              <TableCell>Usuario</TableCell>
              <TableCell>Nombre</TableCell>
              <TableCell>Rol</TableCell>
              <TableCell>Área</TableCell>
              <TableCell>Estado</TableCell>
              <TableCell>Acciones</TableCell>
            </TableRow>
          </TableHead>
          <TableBody>
            {loading ? (
              <TableRow>
                <TableCell colSpan={6} align="center">
                  Cargando usuarios...
                </TableCell>
              </TableRow>
            ) : users.length === 0 ? (
              <TableRow>
                <TableCell colSpan={6} align="center">
                  No hay usuarios registrados. Crea el primer usuario.
                </TableCell>
              </TableRow>
            ) : (
              users.map((user) => (
                <TableRow key={user.id}>
                  <TableCell>{user.username}</TableCell>
                  <TableCell>{user.name}</TableCell>
                  <TableCell>
                    <Chip 
                      label={user.role} 
                      color={getRoleColor(user.role)}
                      size="small"
                    />
                  </TableCell>
                  <TableCell>{user.area || 'Sin área'}</TableCell>
                  <TableCell>
                    <Chip 
                      label={user.is_active ? 'Activo' : 'Inactivo'} 
                      color={user.is_active ? 'success' : 'error'}
                      size="small"
                    />
                  </TableCell>
                  <TableCell>
                    <IconButton 
                      color="primary"
                      onClick={() => handleEditUser(user)}
                    >
                      <Edit />
                    </IconButton>
                    <IconButton 
                      color="secondary"
                      onClick={() => handleResetPassword(user.id)}
                      title="Resetear contraseña"
                    >
                      <LockReset />
                    </IconButton>
                    <IconButton 
                      color="error"
                      onClick={() => handleDeleteUser(user.id)}
                    >
                      <Delete />
                    </IconButton>
                  </TableCell>
                </TableRow>
              ))
            )}
          </TableBody>
        </Table>
      </TableContainer>

      {/* Diálogo para crear/editar usuario */}
      <Dialog open={openDialog} onClose={() => setOpenDialog(false)} maxWidth="sm" fullWidth>
        <DialogTitle>
          {editingUser ? 'Editar Usuario' : 'Crear Nuevo Usuario'}
        </DialogTitle>
        <DialogContent>
          <TextField
            autoFocus
            margin="dense"
            label="Usuario (login)"
            fullWidth
            value={newUser.username}
            onChange={(e) => setNewUser(prev => ({ ...prev, username: e.target.value }))}
            sx={{ mb: 2 }}
            required
            disabled={!!editingUser} // No editar username en edición
          />
          
          <TextField
            margin="dense"
            label={editingUser ? 'Nueva Contraseña (dejar en blanco para no cambiar)' : 'Contraseña'}
            type="password"
            fullWidth
            value={newUser.password}
            onChange={(e) => setNewUser(prev => ({ ...prev, password: e.target.value }))}
            sx={{ mb: 2 }}
            required={!editingUser}
          />
          
          <TextField
            margin="dense"
            label="Nombre Completo"
            fullWidth
            value={newUser.name}
            onChange={(e) => setNewUser(prev => ({ ...prev, name: e.target.value }))}
            sx={{ mb: 2 }}
            required
          />
          
          <FormControl fullWidth sx={{ mb: 2 }}>
            <InputLabel>Rol</InputLabel>
            <Select
              value={newUser.role}
              label="Rol"
              onChange={(e) => setNewUser(prev => ({ ...prev, role: e.target.value }))}
            >
              {roles.map(role => (
                <MenuItem key={role.value} value={role.value}>
                  {role.label}
                </MenuItem>
              ))}
            </Select>
          </FormControl>
          
          <FormControl fullWidth sx={{ mb: 2 }}>
            <InputLabel>Área</InputLabel>
            <Select
              value={newUser.area || ''}
              label="Área"
              onChange={(e) => setNewUser(prev => ({ ...prev, area: e.target.value }))}
            >
              <MenuItem value="">
                <em>Sin área asignada</em>
              </MenuItem>
              {areas.map(area => (
                <MenuItem key={area} value={area}>
                  {area}
                </MenuItem>
              ))}
            </Select>
          </FormControl>
          
          {editingUser && (
            <FormControl fullWidth>
              <InputLabel>Estado</InputLabel>
              <Select
                value={newUser.is_active}
                label="Estado"
                onChange={(e) => setNewUser(prev => ({ ...prev, is_active: e.target.value }))}
              >
                <MenuItem value={true}>Activo</MenuItem>
                <MenuItem value={false}>Inactivo</MenuItem>
              </Select>
            </FormControl>
          )}
        </DialogContent>
        <DialogActions>
          <Button onClick={() => setOpenDialog(false)}>Cancelar</Button>
          <Button 
            onClick={handleSave} 
            variant="contained"
            disabled={(!editingUser && (!newUser.username || !newUser.password || !newUser.name))}
          >
            {editingUser ? 'Actualizar' : 'Crear'}
          </Button>
        </DialogActions>
      </Dialog>
    </Box>
  );
};

export default UsersManagement;
